\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 1\plain \f4\super\lang1033\fs28 ra\plain \f0\fs22 \endash 8\plain \f4\super\lang1033\fs28 va\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f4\scaps\lang1033\fs22\chcbpat17 Johannes Witte de Hese}}\plain \f4\scaps\lang1033\fs22 : [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f4\scaps\lang1033\fs22\chcbpat17 Itinerarium}}\plain \f4\scaps\lang1033\fs22 ]\plain \f0\fs22 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f4\i\lang1033\fs22\chcbpat17 Anno domini m}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f4\i\super\lang1033\fs28\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f4\i\lang1033\fs22\chcbpat17  ccc}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f4\i\super\lang1033\fs28\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f4\i\lang1033\fs22\chcbpat17  lxxxix}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f4\i\super\lang1033\fs28\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f4\i\lang1033\fs22\chcbpat17  Johannes Witte de Hese presbiter Traiectensis diocesis fui in Jherusalem in maio visitando ibi sancta loca}}\plain \f4\i\lang1033\fs22  ... \endash  ... et qualiter ibi sit dispositum pluribus est notum.\plain \f0\fs22  Ed.: Gustav Oppert: Der Presbyter Johannes in Sage und Geschichte. Berlin 1864, S. 180\endash 193 (Hs genannt); Friedrich Zarncke: Der Priester Johannes. Leipzig 1876 (Abh. d. Kgl. S\u228 \'e4chs. Ges. d. Wiss. Philol.-hist. Kl. 8,1), S.\~162\endash 171. Zu Text und \u220 \'dcberlieferung vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 SO StB}}\plain \f0\fs22 , S. 123 (Lit.); Ulrich Knefelkamp: Die Suche nach dem Reich des Priesterk\u246 \'f6nigs Johannes. Gelsenkirchen 1986, S. 74.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Arial;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

