\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f0\fs22 7 VI\plain \f1\super\lang1033\fs28 83\plain \f0\fs22  + IX\plain \f1\super\lang1033\fs28 101\plain \f0\fs22  + 2 VI\plain \f1\super\lang1033\fs28 125\plain \f0\fs22  + VII\plain \f1\super\lang1033\fs28 139\plain \f0\fs22  + (X-2)\plain \f1\super\lang1033\fs28 157\plain \f0\fs22  + 4 VI\plain \f1\super\lang1033\fs28 205\plain \f0\fs22  + V\plain \f1\super\lang1033\fs28 215\plain \f0\fs22  + 4 VI\plain \f1\super\lang1033\fs28 263\plain \f0\fs22 ; teilweise\plain \f1\i\lang1033\fs22  \plain \f0\fs22 Reklamanten; Lagen\-signaturen; alte Blattz\u228 \'e4hlung, Ludolphus de Borchtorpe, M. 15. Jh.; Bll. *2 und Schaltzettel (s. u.) nicht gez\u228 \'e4hlt; Bll. 35bis\endash 35ter und 135b kleinere Schaltzettel auf Pergament (2. H. 14. Jh.)\plain \f0\fs22\cf1  \u183 \'b7 \plain \f0\fs22 Schriftraum 22,5\endash 23,5\plain \f0\fs22\cf1  \u215 \'d7 \plain \f0\fs22 12,5\endash 15,5\plain \f0\fs22\cf1  \u183 \'b7 \plain \f0\fs22 Meist 2 Sp., daneben 1 Sp., teilweise auch 3\endash 4 Sp.\plain \f0\fs22\cf1  \u183 \'b7 \plain \f0\fs22 37\endash 68 Z.\plain \f0\fs22\cf1  \u183 \'b7 {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Kursive und Hybrida}}\plain \f0\fs22 , f\u252 \'fcnf H\u228 \'e4nde (Ludolphus de Borchtorpe, Nicolaus Berlin de Moguntia (?), Hinricus Brunswik u. a.)\plain \f0\fs22\cf1  \u183 \'b7 \plain \f0\fs22 Rote und gr\u252 \'fcne Rubrizierung\plain \f0\fs22\cf1  \u183 \'b7 \plain \f1\lang1033\fs22 Teilweise rot-gr\u252 \'fcn-braune {\field{\*\fldinst HYPERLINK "hida://5270[0]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Initialen}}\plain \f0\fs22  mit Fleuronn\u233 \'e9e, vereinzelt auch mit {\field{\*\fldinst HYPERLINK "hida://5270[2]/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Randst\u228 \'e4ben}}\plain \f0\fs22\cf1  \u183 \'b7 \plain \f0\fs22 Zahlreiche {\field{\*\fldinst HYPERLINK "hida://5270[1]/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17  Tabel