\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22\cf1 198\plain \f1\super\lang1033\fs28\cf1 ra\plain \f1\lang1033\fs22\cf1 -352\plain \f1\super\lang1033\fs28\cf1 rb\plain \f1\lang1033\fs22\cf1  \plain \f1\scaps\lang1033\fs22\cf1 [{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17\cf1 Commentarius] in [Adami Magistri] Summula de Summa Raimundi}}\plain \f1\lang1033\fs22\cf1 . Kommentar und metrischer Text (Redaktion A) blockweise alternierend; Text mit Durchschu\u223 \'df (Interlinearglossierung nicht ausgef\u252 \'fchrt). \u220 \'dcbergeschrieben: \plain \f1\i\lang1033\fs22\cf1 In nomine domini. Amen. \plain \f1\lang1033\fs22\cf1 (198\plain \f1\super\lang1033\fs28\cf1 ra\plain \f1\lang1033\fs22\cf1 -202\plain \f1\super\lang1033\fs28\cf1 rb\plain \f1\lang1033\fs22\cf1 ) Prolog: >\plain \f1\i\lang1033\fs22\cf1 Iube domine benedicere<. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Iube domine benedicere hoc dicto ... in Summula Raimundi metrice compilata collecturus}}\plain \f1\i\lang1033\fs22\cf1  ...\plain \f1\lang1033\fs22\cf1  (202\plain \f1\super\lang1033\fs28\cf1 rb\plain \f1\lang1033\fs22\cf1 -351\plain \f1\super\lang1033\fs28\cf1 va\plain \f1\lang1033\fs22\cf1 ) Text: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Summula de summa Raimundi prodiit ista /}}\plain \f1\lang1033\fs22\cf1  ... - ... \plain \f1\i\lang1033\fs22\cf1 Si funus est presens non est transferre necesse. Finito libro sit laus et glorio Christo.\plain \f1\lang1033\fs22\cf1  (202\plain \f1\super\lang1033\fs28\cf1 va\plain \f1\lang1033\fs22\cf1 -352\plain \f1\super\lang1033\fs28\cf1 rb\plain \f1\lang1033\fs22\cf1 )\plain \f1\i\lang1033\fs22\cf1  \plain \f1\lang1033\fs22\cf1 Kommentar: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17\cf1 Iste liber, de cuius subiecto visum est in precedentibus, dividitur in novem capitula}}\plain \f1\i\lang1033\fs22\cf1  ... - ... quia dies dominicus peragitur propter resurrectionem Christi, per quam ipse electos suos ab inferis traxit et ad vitam eternam perduxit, ad quam eciam nos perducere dignetur pater et filius et spiritus sanctus. Amen.\plain \f1\lang1033\fs22\cf1  Zu Verfasser, Werk (Text) und \u220 \'dcberlieferung vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17\cf1 VL (2)}}\plain \f1\lang1033\fs22\cf1 , Bd. 1, Sp. 47-50 (Lit.); {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17\cf1 Walther, Initia, 1969}}\plain \f1\lang1033\fs22\cf1 , Nr. 9117; 18895; {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17\cf1 Bloomfield/Guyot, Incipits, 1979}}\plain \f1\lang1033\fs22\cf1 , Nr. 5852; {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17\cf1 MZ StB Kat. 2}}\plain \f0\fs22\cf1 , S. 276\plain \f1\lang1033\fs22\cf1 . \u220 \'dcberlieferung auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f0\fs22\chcbpat17\cf1 Greifswald, GM, XXIX.E.4.}}\plain \f1\lang1033\fs22\cf1 , 11\plain \f1\super\lang1033\fs28\cf1 ra\plain \f1\lang1033\fs22\cf1 -249\plain \f1\super\lang1033\fs28\cf1 ra\plain \f1\lang1033\fs22\cf1  (Kommentar). 340\plain \f1\super\lang1033\fs28\cf1 ra\plain \f1\lang1033\fs22\cf1 -346\plain \f1\super\lang1033\fs28\cf1 vb\plain \f1\lang1033\fs22\cf1  (Text) (Leipzig, 1425-1429), vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17\cf1 HGW GM, UB, UA}}\plain \f1\lang1033\fs22\cf1 , S. 120f. (Abweichungen). \plain \f0\fs22\cf1 Am Rand vereinzelt Glossen des Rubrikators (= Hand 2 und Schreiber von Teil I-II, s.o.). \plain \f1\lang1033\fs22\cf1 352\plain \f1\super\lang1033\fs28\cf1 v\plain \f1\lang1033\fs22\cf1  leer. Handwechsel. }

