\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 80\plain \f0\super\fs28 ra\plain \f0\fs22 -82\plain \f0\super\fs28 vb\plain \f0\fs22  \plain \f0\scaps\fs22 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Johannes de Deo}}\plain \f0\scaps\fs22 ]: {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Abbreviatio Decreti}}\plain \f0\fs22 . (80\plain \f0\super\fs28 r\plain \f0\fs22 ) \u220 \'dcbergeschriebener Versus von Rodevo\u223 \'df: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Auctor distinguit et i dat triginta causas cum vi }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (korr. }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 causas x tria cum vi}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 )}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17  / Penitet v versum sed vult consecrare reversum }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (korr. }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 consecrat inde reversum}}\plain \f0\i\fs22 ).\plain \f0\fs22  (80\plain \f0\super\fs28 ra\plain \f0\fs22 ) Prolog: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Incipit Abbreviatio Decreti, in qua sub planis et brevibus verbis continetur tota vis et intencio doctorum}}\plain \f0\i\fs22  ... \plain \f0\fs22 Text: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Liber ergo Decretorum distinctus est in tres partes}}\plain \f0\i\fs22  ... - ... In v 'De confirmacione et ieiunio' \u167 \'a7 'Dictum est'. Et sic terminatur liber iii 'Duobus' \u167 \'a7 'De spiritu sancto'. >Explicit auratum Decretum sic breviatum<.\plain \f0\fs22  Zum Verfasser, Werk und \u220 \'dcberlieferung vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Stintzing, Geschichte, 1867}}\plain \f0\fs22 , S. 38-41; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Schulte, Geschichte, 1875}}\plain \f0\fs22 , Bd. 2, S. 96; {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 D\u237 \'edaz y D\u237 \'edaz, Index, 1958}}\plain \f0\fs22 , Nr. 1267. \plain \f0\fs22\cf1 Am Rand vereinzelt Glossen von Rodevo\u223 \'df (zwei Schichten). \plain \f0\fs22 Handwechsel.}

