\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 1\plain \f0\super\fs28 ra\plain \f0\fs22 -4\plain \f0\super\fs28 rb\plain \f0\fs22  \plain \f0\scaps\fs22 [{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Petrus Pictaviensis}}\plain \f0\fs22  u.a.\plain \f0\scaps\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Compendium historiae in genealogia Christi}}\plain \f0\scaps\fs22 ]\plain \f0\fs22 . Mit Stammb\u228 \'e4umen biblischer Personen und antiker Herrscher (Sch\u246 \'f6pfung bis zum Ende der Hasmon\u228 \'e4er- bzw. Makkab\u228 \'e4erdynastie). Prolog: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Considerans hystorie sacre prolixitatem}}\plain \f0\i\fs22  ... \plain \f0\fs22 (1\plain \f0\super\fs28 rb\plain \f0\fs22 ) Text: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Adam in agro Damasceno formatus est }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (!) }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 et in paradisum}}\plain \f0\i\fs22  ... - ... Schaurus \plain \f0\fs22 (!) \plain \f0\i\fs22 fuit primus preses Syrie dicti \plain \f0\fs22 (!) \plain \f0\i\fs22 de quo sequntur \plain \f0\fs22 (!) \plain \f0\i\fs22 ut \plain \f0\fs22 (!) \plain \f0\i\fs22 Gabinus \plain \f0\fs22 (!) \plain \f0\i\fs22 etc. \plain \f0\fs22 Schlu\u223 \'df unleserlich. Nur am Anfang (bis 1\plain \f0\super\fs28 rb\plain \f0\fs22 ) von Petrus Pictaviensis, danach unbekannte Quellen zum Alten Testament. Ed.: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Moore, Work of Peter of Poitiers}}\plain \f0\fs22 , S. 99 (Prolog); 188-196 (Text; 1\plain \f0\super\fs28 ra\plain \f0\fs22 -1\plain \f0\super\fs28 rb\plain \f0\fs22 ). Zu Verfasser, Werk und \u220 \'dcberlieferung vgl. ebd., S. 97-117; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Stegm\u252 \'fcller RB}}\plain \f0\fs22 , Nr. 6678.}

