\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 1\plain \f0\super\fs28 r\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Liturgische Beleuchtungsanweisung (Kerzen)}}\plain \f0\fs22  f\u252 \'fcr Kapitel und Klosterkirche Werden, westf\u228 \'e4l. Nachtrag, 2. H. 14. Jh. (gestrichen). Darunter lat. Vermerk zum Anschlu\u223 \'df Werdens an die Bursfelder Reform (1474), Nachtrag Anf. 16. Jh. Handwechsel.}

