\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1041\fs22 7\plain \f1\super\lang1041\fs24 ra-vb\plain \f1\lang1041\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1041\fs22\chcbpat17 [Calendarium] de festis Romanae Curiae}}\plain \f1\lang1041\fs22 . \plain \f1\i\lang1041\fs22 Festa in Romana Curia servanda de mandato ... Johannis divina providentia Pape XXII. ...\plain \f2\i\lang1033\fs22  \u8250 \'9bJanuarius.\u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1041\fs22\chcbpat17 Festum circumsicionis (!) usque ad crastinum Ephiphanie domini exclusive}}\plain \f1\i\lang1041\fs22  ... - ... Item die qua coronatus fuit papa non est audiencia.\plain \f1\lang1041\fs22  \plain \f5\lang1033\fs22 Entstehung nach Erw\u228 \'e4hnung von Personen und Funktionen wohl um 1327/32 am p\u228 \'e4pst\-li\-chen Hof in Avignon.}

