\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 16\plain \f0\super\fs28 v\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Johannes Frank}}\plain \f0\scaps\fs22  (?): {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Passio in Romana curia secundum aurum et argentum}}\plain \f0\fs22 . Evangelien- bzw. Passionsparodie. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 In illo turbine dixit dominus papa cardinalibus suis: Quando venit filius hominis ad sedem maiestatis}}\plain \f0\i\fs22  ... - ... et si nichil habueris in gaudium huiusmodi non intrabis. \plain \f0\fs22 Direkt angeschlossen Verfassername (?): \plain \f0\i\fs22 Jo[hannes?]. Frank h.\plain \f0\fs22  (nicht identifiziert). \u220 \'dcberlieferung auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Zwettl, StiftsB}}\plain \f0\fs22 , Cod. Zwetl. 209, 419\plain \f0\super\fs28 r\plain \f0\fs22 , vgl. Charlotte Ziegler: Zisterzienserstift Zwettl: Katalog der Handschriften des Mittelalters, Teil 3: Codex 201-300. M\u252 \'fcnchen 1989, S. 27 (anonym; Explicit abweichend). Danach kurzer Nachtrag von Rodevo\u223 \'df zu den Konzils- bzw. Gegenp\u228 \'e4psten Johannes XXIII. (reg. 1410-1415), Benedikt XIII. (reg. 1394-1409/17) und Gregor XII. (reg. 1406-1409/15).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 17\plain \f0\super\fs28 r\plain \f0\fs22 -26\plain \f0\super\fs28 v\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Prozessakten}}\plain \f0\fs22  des Merseburger Offizialats, ostf\u228 \'e4lisch mit lat. Einsprengseln (zivilrechtliche Bez\u252 \'fcge). Gerichtsprozess nach {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6923/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Magdeburg}}\plain \f0\fs22 er Recht zwischen \plain \f0\i\fs22 Hans Waltheym\plain \f0\fs22  und \plain \f0\i\fs22 Anna\plain \f0\fs22 , Witwe des Ritters \plain \f0\i\fs22 Marquard von Nitzenplitz\plain \f0\fs22  (Itzenplitz). Inhaltliche Bez\u252 \'fcge auf Leipzig, Wittenberg u.a., 1445-1447. Titel: \plain \f0\i\fs22 Causa teutunicalis\plain \f0\fs22  (!) \plain \f0\i\fs22 et bone de consuetudine.\plain \f0\fs22  Am Rand Glossen von Rodevo\u223 \'df, nd.-lat. (Ausarbeitung als Prozessmuster, vgl. auch Titel). Handwechsel.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

