\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 33\plain \f0\super\fs28 v\plain \f0\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Vita [sive Historia] Neminis}}\plain \f0\fs22 , Fassung C. Legendenparodie. Nachtrag von Rodevo\u223 \'df. Titel (\plain \f0\i\fs22 Vita Nemonis\plain \f0\fs22 ) von Rodevo\u223 \'df korrigiert: \plain \f0\i\fs22 Sermo de Sancto Nemine\plain \f0\fs22 . Text: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Erat vir in oriente, cuius nomen Nemo, et iste vir erat ut alter Job}}\plain \f0\i\fs22  ... - ... Vir iste Nemo videns omnia huius mundi esse vana et inutilia, ascendit in celum secundum apostolum Johannem, qui dicit: 'Nemo ascendit in celum' et ergo ascensio domini nostri Jhesu Christi perducat nos una cum Nemine in vitam eternam.\plain \f0\fs22  Zum Werk vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Lehmann, Parodie, 1963}}\plain \f0\fs22 , S. 176-178, v.a. S. 177 (Fassung C). Urspr\u252 \'fcnglich folgend Berlin, SB, Ms. lat. fol. 297.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

