\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 55\plain \f0\super\fs28 r\plain \f0\fs22 -75\plain \f0\super\fs28 v\plain \f0\fs22  \plain \f0\scaps\fs22 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Johannes Milicius}}\plain \f0\scaps\fs22 , {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Henricus Totting}}\plain \f0\fs22  (?) u.a.\plain \f0\scaps\fs22 ]: {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f0\scaps\fs22\chcbpat17 Sermones synodales [Pragenses}}\plain \f0\scaps\fs22 ]\plain \f0\fs22 . Sammlung von sieben Predigten (Nr. 1-3; 4-8), teilweise (Nr. 1; 3) Prager Provenienz (E. 14. Jh.), mit eingeschobener Oratio (Sachsen [Leipzig?] bzw. Havelberg) (Nr. 4). Nr. 1 (55\plain \f0\super\fs28 r\plain \f0\fs22 -58\plain \f0\super\fs28 v\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 >}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Sacerdotes contempserunt legem meam ... }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (Ez 22,26)}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 <. Reverendi patres et domini, sicut Deus pater omnipotens pro salute generis humani misit patres sanctos et prophetas}}\plain \f0\i\fs22  ...\plain \f0\fs22  Ed.: Vil\u233 \'e9m Herold / Milan Mr\u225 \'e1z: Johannis Milicii de Cremsir tres sermones synodales. Prag 1974, S. 49-70. Nr. 2 (58\plain \f0\super\fs28 v\plain \f0\fs22 -62\plain \f0\super\fs28 v\plain \f0\fs22 ) \plain \f0\i\fs22 >{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Recepisti bona et vita tua ... }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (Lc 16,25)}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 <. Reverendi patres et domini et Deo prestantissimi fratresque in Christo carissimi, kathegorizando }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (!) }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 in hac sacra synodo}}\plain \f0\i\fs22  ... \plain \f0\fs22 Nr. 3 (63\plain \f0\super\fs28 r\plain \f0\fs22 -66\plain \f0\super\fs28 v\plain \f0\fs22 ) \plain \f0\i\fs22 >{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Parasti in conspectu meo mensam ... }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (Ps 22,5)}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 <. Reverendi, mensa ista, quam in conspectu meo paratam esse}}\plain \f0\i\fs22  ... - ... et sanguinem suum contulit nobis ad bibendum, dominus noster Jhesus Christus in secula seculorum benedictus. Amen.\plain \f0\fs22  Zum Werk vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Schneyer, Repertorium 2, 1990-1994}}\plain \f0\fs22 , s.v. 'Henricus Totting de Oyta', Nr. 8 (nur Anfang). Nr. 4 (66\plain \f0\super\fs28 v\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Reverendissimi domini mei, quia nunc tempus miserendi venit, ideo principaliter hortor devociones vestras pro singulis necessitatibus}}\plain \f0\i\fs22  ...\plain \f0\fs22  Aufruf zum allgemeinen Gebet f\u252 \'fcr Papst Nikolaus V. [reg. 1447-1455], die Kardin\u228 \'e4le und Bisch\u246 \'f6fe, namentlich den (ungenannten) Bf. {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6923/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Havelberg}}\plain \f0\fs22 , sowie die F\u252 \'fcrsten, namentlich den (ungenannten) Hz. von Sachsen, Th\u252 \'fcringen und Mei\u223 \'dfen, zur Befriedung kirchlicher Streitigkeiten. Nr. 5 (67\plain \f0\super\fs28 r\plain \f0\fs22 -68\plain \f0\super\fs28 r\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Qui me iudicat, dominus est ... }}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (I Cor 4,4)}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 . Reverendi, Chrisostomus in 'De laude pauperum' Omelie vi: Sic, inquit, sicut cibis et deliciis caro}}\plain \f0\i\fs22  ...\plain \f0\fs22  Nr. 6 (68\plain \f0\super\fs28 v\plain \f0\fs22 -72\plain \f0\super\fs28 r\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Cepit lavare ... }}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (Io 13,5)}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 . Reverendi, nam teste Gregorii libro Moralia xi xxv seu finali capitulo homo corruptibili carne vivens}}\plain \f0\i\fs22  ... \plain \f0\fs22 Nr. 7 (72\plain \f0\super\fs28 r\plain \f0\fs22 -74\plain \f0\super\fs28 r\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Paraclitus autem ... }}{\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (Io 14,26)}}{\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 . Reverendi, ex themate preassumpto tria eliciuntur nobis necessaria}}\plain \f0\i\fs22  ... \plain \f0\fs22 Nr. 8 (74\plain \f0\super\fs28 r\plain \f0\fs22 -75\plain \f0\super\fs28 v\plain \f0\fs22 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 Ostendite vos sacerdotibus ... }}{\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 (Lc 17,14)}}{\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f0\i\fs22\chcbpat17 . Reverendi patres, ostensio, que sit sacerdotibus, est una pars penitencie}}\plain \f0\i\fs22  ... \plain \f0\fs22 Am Rand Glossen von Rodevo\u223 \'df. Urspr\u252 \'fcnglich folgend Berlin, SB, Ms. boruss. 720a (I).}

