\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f0\fs22 14\plain \f4\super\lang1033\fs28 rb\plain \f0\fs22 \endash 36\plain \f4\super\lang1033\fs28 vb\plain \f0\fs22  \plain \f4\scaps\lang1033\fs22 [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f4\scaps\lang1033\fs22\chcbpat17 Aristoteles}}\plain \f4\scaps\lang1033\fs22 :] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f4\scaps\lang1033\fs22\chcbpat17 De anima}}\plain \f4\scaps\lang1033\fs22 . [\plain \f0\fs22 Translatio nova von\plain \f4\scaps\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f4\scaps\lang1033\fs22\chcbpat17 Guilelmus de Moerbeka}}\plain \f4\scaps\lang1033\fs22 ]. \plain \f4\scaps\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f4\i\lang1033\fs22\chcbpat17 Bonorum honorabilium notitiam opinantes magis autem alteram altera que aut secundum certitudinem}}\plain \f4\i\lang1033\fs22  \u8230 \'85 \endash  \u8230 \'85 linguam autem quatenus aliquid alteri. Explicit Liber de anima. Amen. \plain \f0\fs22 Ed.: Sancti Thomae de Aquino opera omnia iussu Leonis XIII P.M. edita, Bd. 45/1: Sentencia Libri de anima. Rom u. a. 1984, S. 3\endash 258. Zum Werk vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Thorndike/Kibre, Catalogue of Incipits, 1963}}\plain \f0\fs22 , Sp. 179; {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Hamesse/Szyller, Repertorium, 2007\endash 2009}}\plain \f0\fs22 , Nr.\~5071 (vgl. auch Nr. 5078\endash 5080); {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f0\fs22\chcbpat17 Sch\u246 \'f6nberger, Repertorium (2), 2011}}\plain \f0\fs22 , S. 584 (A9600-120). \plain \f4\lang1033\fs22 Am Rand sowie zwischen den Zeilen vereinzelte Nachtr\u228 \'e4ge von Schreiberhand sowie zahlreiche Glossen, vier H\u228 \'e4nde, 2. Dr. 14. Jh.}

